  'Follistatin 344':{category:'Muscle Growth',tagline:'Myostatin inhibitor — muscle growth beyond genetic limits',mechanism:'Naturally occurring glycoprotein binding and inhibiting myostatin. By blocking myostatin, follistatin allows muscle mass to increase beyond your genetic ceiling.',benefits:['Dramatic muscle growth by removing myostatin ceiling','Increased muscle fiber size and number','Potential treatment for muscular dystrophy'],sideEffects:[{text:'Very limited human safety data',severity:'high'},{text:'Theoretical oncologic risk (activin inhibition)',severity:'high'},{text:'Unknown long-term effects',severity:'high'}],timeline:[{time:'Wk 1–4',text:'Muscle fullness increase'},{time:'Wk 4–8',text:'Size gains beyond normal rate'}],schedule:'SubQ — short burst protocols',cycle:'10–20 day burst cycles only',lo:'50 mcg/day SubQ × 10 days (burst cycle — extremely limited human data)',mid:'100 mcg/day SubQ × 10 days',hi:'200 mcg/day SubQ × 10 days — NO human RCT data. Cancer risk theoretical concern (myostatin inhibition). Medical supervision mandatory.',pairsWith:['IGF-1 LR3','HGH'],avoid:['Cancer history','Long continuous cycles'],evidence:1,evidenceNote:'Gene therapy data in muscular dystrophy. Very limited peptide injection human data.',studies:[{title:'Follistatin Gene Therapy for Becker Muscular Dystrophy',journal:'Molecular Therapy 2015',summary:'Phase 1/2a trial of follistatin gene therapy in Becker muscular dystrophy patients. Demonstrated safety and increased muscle mass — proof of concept for myostatin inhibition via follistatin.',pmid:'25322757',url:'https://pubmed.ncbi.nlm.nih.gov/25322757/'}]},
  'Dihexa':{category:'Cognitive',tagline:'Most potent nootropic peptide — 7 million times stronger than BDNF',mechanism:'HGF mimetic activating MET receptor. Promotes synaptogenesis 7 million times more potently than BDNF. Developed at WSU for Alzheimers.',benefits:['Synaptogenesis — new neural connections','Cognitive enhancement','Potential Alzheimers therapeutic'],sideEffects:[{text:'Very limited human safety data — experimental',severity:'high'},{text:'Theoretical cancer risk (HGF/MET pathway)',severity:'high'},{text:'Long half-life — effects persist long after dosing',severity:'med'}],timeline:[{time:'Days 1–14',text:'Cognitive effects emerge gradually'},{time:'Post-cycle',text:'Effects persist due to long half-life'}],schedule:'SubQ or intranasal — very cautious',cycle:'4 weeks max',lo:'5 mg/wk',mid:'10 mg/wk',hi:'15 mg/wk',pairsWith:['Semax','NAD+'],avoid:['Cancer history','Without full understanding of risks'],evidence:1,evidenceNote:'Animal data only. No published human trials. Highly experimental. CRITICAL: The two foundational Dihexa papers (Kawas 2012, Benoist 2014, J Pharmacol Exp Ther) were retracted in April 2025 due to data fabrication by a co-author. The 7-million-times-BDNF claim originated from these retracted papers.',studies:[{title:'Dihexa Combined with Stem Cells and G-CSF for Sciatic Nerve Recovery in Rats',journal:'Annals of Medicine and Surgery 2021',summary:'Dihexa combined with stem cells and G-CSF improved limb function recovery in a rat sciatic nerve damage-repair model.',pmid:'34703584',url:'https://pubmed.ncbi.nlm.nih.gov/34703584/'}]},
