  'Retatrutide':{category:'Weight Loss',tagline:'Triple GIP+GLP-1+glucagon agonist — 28.7% weight loss in Phase 3. Most potent obesity drug in trial history.',mechanism:'Triple receptor agonist: GLP-1 (appetite suppression), GIP (insulin/fat metabolism), glucagon (energy expenditure). The glucagon component uniquely increases caloric burn — this is why retatrutide outperforms all dual agonists. Phase 3 TRIUMPH-4 showed 28.7% weight loss at 12mg over 68 weeks — highest ever recorded in a Phase 3 obesity trial.',benefits:['28.7% average body weight loss at 12mg (Phase 3 TRIUMPH-4, 68 weeks) — highest ever in a Phase 3 trial','No weight loss plateau at 48 weeks (Phase 2 data)','80%+ liver fat reduction','Significant knee osteoarthritis pain reduction in TRIUMPH-4 (-75.8% WOMAC score)','Improvements in all cardiometabolic markers including cholesterol and blood pressure','7 more Phase 3 readouts expected throughout 2026'],sideEffects:[{text:'Nausea (43% at 12mg) — titrate extremely slowly to minimize',severity:'med'},{text:'Diarrhea (33%)',severity:'low'},{text:'Vomiting (~20%)',severity:'med'},{text:'Dysesthesia (abnormal skin sensation — burning, tingling) at 20.9% vs 0.7% placebo — new Phase 3 signal. FDA monitoring.',severity:'med'},{text:'Not FDA approved — NDA submission expected late 2026; approval estimated 2027–2028',severity:'high'}],timeline:[{time:'Wk 1–4',text:'Appetite suppression; GI adjustment during titration'},{time:'Wk 4–24',text:'Accelerating weight loss through titration steps'},{time:'Wk 24–68',text:'Up to 28.7% total weight loss at Phase 3 doses'}],schedule:'Once weekly SubQ — titrate extremely slowly. Spend 6–8 weeks at each dose step minimum.',cycle:'48+ weeks for maximum benefit — do not rush titration',lo:'1 mg/wk × 8 wks → 2 mg/wk × 8 wks (very conservative)',mid:'1→2→4→8 mg/wk (6–8 wks per step) — Phase 2/3 protocol',hi:'Up to 12 mg/wk maximum — Phase 3 highest dose',pairsWith:['NAD+','5-amino-1mq'],avoid:['Semaglutide','Tirzepatide — never combine GLP-1 class compounds','CagriSema — never stack with other GLP-1 agents'],evidence:3,evidenceNote:'Phase 2 NEJM RCT 2023 (338 participants, 24.2% at 48 wks). Phase 3 TRIUMPH-4 December 2025: 28.7% at 68 weeks — highest ever Phase 3 result. 7 more Phase 3 readouts in 2026. NDA submission expected late 2026.',studies:[{title:'Retatrutide for Obesity: Phase 2 Trial',journal:'NEJM 2023',summary:'338 obese adults. 24.2% weight loss at 48 weeks. 100% on 8–12mg achieved ≥5% loss. Historic Phase 2 data.',pmid:'37366315',url:'https://pubmed.ncbi.nlm.nih.gov/37366315/'},{title:'TRIUMPH-4: Retatrutide Phase 3 — 28.7% Weight Loss',journal:'Eli Lilly Press Release / Phase 3 2025',summary:'445 adults with obesity and knee osteoarthritis. Retatrutide 12mg: 28.7% average weight loss at 68 weeks — highest ever Phase 3 result. Also reduced WOMAC pain by 75.8%. New dysesthesia signal at 20.9%.',pmid:'',url:'https://investor.lilly.com/news-releases/news-release-details/lillys-triple-agonist-retatrutide-delivered-weight-loss-average'}]},
